package main

import (
    "errors"
    "fmt"
    "os"
    "os/exec"
    "regexp"
    "strconv"
)

func MeasureLatency(host string, count int) (float64, error) {
    if count <= 0 {
        return 0, errors.New("count must be positive")
    }
    cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
    output, err := cmd.Output()
    if err != nil {
        return 0, fmt.Errorf("ping command failed: %v", err)
    }
    outStr := string(output)
    // Parse lines for time=XX.X ms
    re := regexp.MustCompile(`time=([0-9]+\.?[0-9]*) ms`)
    matches := re.FindAllStringSubmatch(outStr, -1)
    if len(matches) == 0 {
        return 0, errors.New("no ping responses received")
    }
    var total float64
    for _, match := range matches {
        t, err := strconv.ParseFloat(match[1], 64)
        if err != nil {
            continue // skip if parse error (shouldn't happen)
        }
        total += t
    }
    avg := total / float64(len(matches))
    return avg, nil
}

func main() {
    if len(os.Args) != 3 {
        fmt.Fprintf(os.Stderr, "Usage: %s <host> <count>\n", os.Args[0])
        os.Exit(1)
    }
    host := os.Args[1]
    count, err := strconv.Atoi(os.Args[2])
    if err != nil || count <= 0 {
        fmt.Fprintf(os.Stderr, "Invalid count: %s\n", os.Args[2])
        os.Exit(1)
    }
    avg, err := MeasureLatency(host, count)
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error: %v\n", err)
        os.Exit(1)
    }
    fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

