// MeasureLatency pings a host a specified number of times and returns the
// average round-trip time in milliseconds. The implementation uses the
// system's ping command via os/exec.
func MeasureLatency(host string, count int) (float64, error) {
	var cmd *exec.Cmd

	switch runtime.GOOS {
	case "linux", "darwin": // macOS and Linux use -c for count
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default:
		// Fallback: try the Unix-style flags
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w\noutput: %s", err, output)
	}

	return parsePingOutput(string(output), runtime.GOOS)
}

// parsePingOutput extracts the average latency in milliseconds from the
// output of the ping command. It supports Linux, macOS, and Windows.
func parsePingOutput(output string, goos string) (float64, error) {
	switch goos {
	case "linux", "darwin":
		// Examples:
		// Linux:   rtt min/avg/max/mdev = 1.234/2.345/3.456/0.567 ms
		// macOS:   round-trip min/avg/max/stddev = 1.234/2.345/3.456/0.567 ms
		re := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max.*?=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
		matches := re.FindStringSubmatch(output)
		if len(matches) < 2 {
			return 0, fmt.Errorf("could not parse average latency from output:\n%s", output)
		}
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average value %q: %w", matches[1], err)
		}
		return avg, nil

	case "windows":
		// Example: Average = 12ms
		re := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
		matches := re.FindStringSubmatch(output)
		if len(matches) < 2 {
			return 0, fmt.Errorf("could not parse average latency from output:\n%s", output)
		}
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average value %q: %w", matches[1], err)
		}
		return avg, nil

	default:
		return 0, fmt.Errorf("unsupported operating system: %s\noutput:\n%s", goos, output)
	}
}

func main() {
	host := flag.String("host", "google.com", "target host to ping")
	count := flag.Int("count", 4, "number of ping requests")
