package main

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strconv"
)

// MeasureLatency pings the given host a specified number of times and returns
// the average round-trip latency in milliseconds.
// This implementation uses the system's ping command and assumes a Unix-like
// operating system (Linux, macOS). It will not work on Windows without
// adjusting the command flags.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command. The -c flag sets the number of packets.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v", err)
	}

	// Regular expression to extract time values like "time=12.345 ms"
	re := regexp.MustCompile(`time=(\d+(?:\.\d+)?)\s*ms`)
	matches := re.FindAllStringSubmatch(string(output), -1)
	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency information found in ping output")
	}

	var total float64
	for _, match := range matches {
		ms, err := strconv.ParseFloat(match[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse latency value: %v", err)
		}
		total += ms
	}

	return total / float64(len(matches)), nil
}

func main() {
	// Default values
	host := "google.com"
	count := 4

	// Override with command-line arguments, if provided
	if len(os.Args) >= 2 {
		host = os.Args[1]
	}
	if len(os.Args) >= 3 {
		if c, err := strconv.Atoi(os.Args[2]); err == nil && c > 0 {
			count = c
		} else {
			fmt.Fprintf(os.Stderr, "Invalid count, using default %d\n", count)
		}
	}

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

