package main

import (
	"flag"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a host a specified number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	avg, err := parsePingOutput(string(output), runtime.GOOS)
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}
	return avg, nil
}

// parsePingOutput extracts the average latency from ping output string.
func parsePingOutput(out string, goos string) (float64, error) {
	if goos == "windows" {
		// Windows output: "Average = Xms" (could be X ms)
		re := regexp.MustCompile(`Average\s*=\s*(\d+(?:\.\d+)?)\s*ms`)
		matches := re.FindStringSubmatch(out)
		if len(matches) < 2 {
			return 0, fmt.Errorf("could not find average in output: %s", out)
		}
		return strconv.ParseFloat(matches[1], 64)
	} else {
		// Linux/macOS: "rtt min/avg/max/mdev = 1.234/2.345/3.456/0.567 ms"
		re := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+\/([\d.]+)\/[\d.]+\/[\d.]+\s*ms`)
		matches := re.FindStringSubmatch(out)
		if len(matches) < 2 {
			return 0, fmt.Errorf("could not find rtt avg in output: %s", out)
		}
		return strconv.ParseFloat(matches[1], 64)
	}
}

func main() {
	host := flag.String("host", "google.com", "Target host to ping")
	count := flag.Int("count", 4, "Number of ping attempts")
	flag.Parse()

	if *count <= 0 {
		fmt.Fprintf(os.Stderr, "Error: count must be a positive integer\n")
		os.Exit(1)
	}

	avg, err := MeasureLatency(*host, *count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Average latency to %s: %.2f ms\n", *host, avg)
}

