package main

import (
	"fmt"
	"os"
	"os/exec"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency measures the average network latency to a host by sending a
// specified number of ping requests. It returns the average round-trip time in
// milliseconds or an error if something goes wrong.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("invalid count: must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		// Windows uses -n for count and outputs "Average = Xms"
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		// Unix-like systems (Linux, macOS) use -c for count
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	return parseLatency(string(output), runtime.GOOS)
}

// parseLatency extracts the average latency from ping command output.
// The parsing strategy differs between Windows and Unix-like systems.
func parseLatency(output string, goos string) (float64, error) {
	lines := strings.Split(output, "\n")

	if goos == "windows" {
		// Example Windows output line: "    Average = 10ms"
		for _, line := range lines {
			if strings.Contains(line, "Average") && strings.Contains(line, "ms") {
				parts := strings.Split(line, "=")
				if len(parts) < 2 {
					continue
				}
				avgStr := strings.TrimSpace(parts[1])
				avgStr = strings.TrimSuffix(avgStr, "ms")
				avgStr = strings.TrimSpace(avgStr)
				avg, err := strconv.ParseFloat(avgStr, 64)
				if err != nil {
					return 0, fmt.Errorf("failed to parse average latency: %v", err)
				}
				return avg, nil
			}
		}
		return 0, fmt.Errorf("average latency not found in ping output")
	}

	// Unix-like output: "rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms"
	// Some versions omit mdev.
	for i := len(lines) - 1; i >= 0; i-- {
		line := lines[i]
		if strings.Contains(line, "min/avg/max") {
			parts := strings.Split(line, "=")
			if len(parts) < 2 {
				continue
			}
			stats := strings.TrimSpace(parts[1])
			// Remove trailing " ms" if present
			stats = strings.TrimSuffix(stats, " ms")
			fields := strings.Split(stats, "/")
			if len(fields) < 2 {
				continue
			}
			avgStr := strings.TrimSpace(fields[1])
			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("failed to parse average latency: %v", err)
			}
			return avg, nil
		}
	}
	return 0, fmt.Errorf("average latency not found in ping output")
}

func main() {
	if len(os.Args) < 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s <host> <count>\n", os.Args[0])
		os.Exit(1)
	}

	host := os.Args[1]
	count, err := strconv.Atoi(os.Args[2])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Invalid count: %v\n", err)
		os.Exit(1)
	}

	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, latency)
}

