// MeasureLatency pings a host a specified number of times and returns
// the average round-trip time in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
    var cmd *exec.Cmd
    if runtime.GOOS == "windows" {
        // Windows uses -n for count, -w for timeout (not used here)
        cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
    } else {
        // Unix-like systems (Linux, macOS) use -c for count
        cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
    }

    output, err := cmd.CombinedOutput()
    if err != nil {
        return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
    }

    outStr := string(output)

    if runtime.GOOS == "windows" {
        // Windows output example: "Average = 123ms"
        re := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
        matches := re.FindStringSubmatch(outStr)
        if len(matches) < 2 {
            return 0, fmt.Errorf("could not parse average latency from output: %s", outStr)
        }
        avg, err := strconv.ParseFloat(matches[1], 64)
        if err != nil {
            return 0, fmt.Errorf("could not parse average latency value: %v", err)
        }
        return avg, nil
    }

    // Unix-like output example:
    // rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
    // or round-trip min/avg/max/stddev = ...
    lines := strings.Split(outStr, "\n")
    for _, line := range lines {
        if strings.Contains(line, "rtt min/avg/max/mdev") ||
            strings.Contains(line, "round-trip") {
            parts := strings.Split(line, "=")
            if len(parts) < 2 {
                continue
            }
            stats := strings.TrimSpace(parts[1])
            stats = strings.TrimSuffix(stats, " ms")
            stats = strings.TrimSpace(stats)
            fields := strings.Split(stats, "/")
            if len(fields) >= 2 {
                avgStr := fields[1] // avg is the second field
                avg, err := strconv.ParseFloat(avgStr, 64)
                if err != nil {
                    return 0, fmt.Errorf("could not parse average latency: %v", err)
                }
                return avg, nil
            }
        }
    }

    return 0, fmt.Errorf("average latency not found in output: %s", outStr)
}

func main() {
    if len(os.Args) < 3 {
        fmt.Fprintf(os.Stderr, "Usage: %s <host> <count>\n", os.Args[0])
        os.Exit(1)
    }
    host := os.Args[1]
    count, err := strconv.Atoi(os.Args[2])
    if err != nil {
        fmt.Fprintf(os.Stderr, "Invalid count: %v\n", err)
        os.Exit(1)
