		}
		avgStr = matches[1]
	}

	avg, err := strconv.ParseFloat(strings.TrimSpace(avgStr), 64)
	if err != nil {
		return 0, fmt.Errorf("invalid average value '%s': %w", avgStr, err)
	}

	return avg, nil
}

