	if len(os.Args) != 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s <host> <count>\n", os.Args[0])
		os.Exit(1)
	}

	host := os.Args[1]
	count, err := strconv.Atoi(os.Args[2])
	if err != nil || count <= 0 {
		fmt.Fprintf(os.Stderr, "Invalid count: %s (must be a positive integer)\n", os.Args[2])
		os.Exit(1)
	}

	avg, err := MeasureLatency(host, count)
