	if err != nil {
		// If the command itself failed, return the error and include the output.
		return 0, fmt.Errorf("ping command failed: %w\nOutput:\n%s", err, string(out))
	}

	// Regular expression that matches "time=X.X ms" or "time<X.Xms" style output.
	// It captures the numeric value including an optional decimal part.
	re := regexp.MustCompile(`time[=<](\d+(?:\.\d+)?)\s*ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		// No round‑trip time information was found (e.g. 100 % packet loss).
		// Clean up the output for a concise error message.
		lines := strings.Split(strings.TrimSpace(string(out)), "\n")
		lastLine := ""
		if len(lines) > 0 {
			lastLine = lines[len(lines)-1]
		}
		return 0, fmt.Errorf("no ping responses received: %s", lastLine)
	}

	// Sum all extracted times and compute the average.
	var total float64
	for _, m := range matches {
		val, err := strconv.ParseFloat(m[1], 64)
		if err != nil {
			continue // paranoia: ignore unparseable values
		}
		total += val
	}

	average := total / float64(len(matches))
	return average, nil
}

func main() {
	// Simple command‑line interface:
	//   program <host> [count]
	// Default count is 4 if not supplied.
	if len(os.Args) < 2 {
		fmt.Fprintf(os.Stderr, "Usage: %s <host> [count]\n", os.Args[0])
		os.Exit(1)
	}

	host := os.Args[1]
	count := 4

	if len(os.Args) >= 3 {
		var err error
		count, err = strconv.Atoi(os.Args[2])
		if err != nil || count <= 0 {
			fmt.Fprintf(os.Stderr, "Invalid count argument. Using default (4).\n")
			count = 4
		}
	}

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(2)
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

