package main

import (
	"flag"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

func MeasureLatency(host string, count int) (float64, error) {
	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v", err)
	}

	re := regexp.MustCompile(`time[=<]\s*(\d+\.?\d*)\s*ms`)
	lines := strings.Split(string(output), "\n")
	var times []float64
	for _, line := range lines {
		matches := re.FindStringSubmatch(line)
		if len(matches) == 2 {
			t, err := strconv.ParseFloat(matches[1], 64)
			if err == nil {
				times = append(times, t)
			}
		}
	}

	if len(times) == 0 {
		return 0, fmt.Errorf("no ping responses received")
	}

	total := 0.0
	for _, t := range times {
		total += t
	}
	return total / float64(len(times)), nil
}

func main() {
	host := flag.String("host", "google.com", "Host to ping")
	count := flag.Int("count", 4, "Number of ping attempts")
	flag.Parse()

	avg, err := MeasureLatency(*host, *count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Average latency to %s: %.2f ms\n", *host, avg)
}

