package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
)

// MeasureLatency pings the specified host a given number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, errors.New("count must be greater than 0")
	}

	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	out, err := cmd.Output()

	re := regexp.MustCompile(`time=(\d+(?:\.\d+)?) ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v; output: %s", err, string(out))
		}
		return 0, fmt.Errorf("no ping responses found in output: %s", string(out))
	}

	var sum float64
	for _, m := range matches {
		val, _ := strconv.ParseFloat(m[1], 64)
		sum += val
	}

	return sum / float64(len(matches)), nil
}

func main() {
	latency, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", latency)
}

