package main

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a host a specified number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("invalid count: %d (must be > 0)", count)
	}

	// Build ping command arguments depending on the operating system
	var args []string
	switch runtime.GOOS {
	case "windows":
		args = []string{"-n", strconv.Itoa(count), host}
	default: // Linux, macOS, etc.
		args = []string{"-c", strconv.Itoa(count), host}
	}

	cmd := exec.Command("ping", args...)
	output, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	// Parse ping output to extract time values (e.g., "time=12.3 ms")
	re := regexp.MustCompile(`time=([0-9]+\.?[0-9]*)\s*ms`)
	matches := re.FindAllStringSubmatch(string(output), -1)
	if len(matches) == 0 {
		return 0, errors.New("no valid ping responses found")
	}

	var total float64
	for _, match := range matches {
		if len(match) < 2 {
			continue
		}
		t, err := strconv.ParseFloat(match[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse time value %q: %w", match[1], err)
		}
		total += t
	}

	average := total / float64(len(matches))
	return average, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	if len(os.Args) >= 2 {
		host = os.Args[1]
	}
	if len(os.Args) >= 3 {
		c, err := strconv.Atoi(os.Args[2])
		if err == nil && c > 0 {
			count = c
		}
	}

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

