package main

import (
	"errors"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Execute ping directly, without a shell, to avoid command injection.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	// Note: ping may return a non-zero exit code if some packets are lost,
	// but it can still output statistics. We continue parsing regardless.

	var statsLine string
	for _, line := range strings.Split(string(output), "\n") {
		if strings.Contains(line, "min/avg/max") {
			statsLine = line
			break
		}
	}

	if statsLine == "" {
		if err != nil {
			return 0, fmt.Errorf("ping failed and no statistics found: %w (output: %s)", err, string(output))
		}
		return 0, errors.New("could not find RTT statistics in ping output")
	}

	// The statistics line has a format like:
	//   rtt min/avg/max/mdev = 12.345/23.456/34.567/5.678 ms   (Linux)
	//   round-trip min/avg/max/stddev = 12.345/23.456/34.567/5.678 ms (macOS)
	// We split by " = " and then extract the second value (the average) from the slash-separated numbers.
	parts := strings.Split(statsLine, " = ")
	if len(parts) != 2 {
		return 0, fmt.Errorf("unexpected stats line format: %s", statsLine)
	}

	values := strings.Split(parts[1], "/")
	if len(values) < 3 {
		return 0, fmt.Errorf("unexpected values format in stats line: %s", parts[1])
	}

	// The second element is the average RTT (may contain trailing " ms" or similar).
	avgStr := values[1]
	avgStr = strings.TrimSpace(avgStr)
	// Strip any trailing unit string (e.g., " ms", "ms").
	if idx := strings.Index(avgStr, " "); idx != -1 {
		avgStr = avgStr[:idx]
	}
	avgStr = strings.TrimSuffix(avgStr, "ms")
	avgStr = strings.TrimSpace(avgStr)

	avg, parseErr := strconv.ParseFloat(avgStr, 64)
	if parseErr != nil {
		return 0, fmt.Errorf("failed to parse average latency '%s': %w", avgStr, parseErr)
	}

	// Even if the ping command returned an error (e.g., partial loss), we successfully
	// obtained a measurement, so we return it.
	return avg, nil
}

