// parsePingOutput extracts the average round-trip time from the ping command output.
func parsePingOutput(output string, goos string) (float64, error) {
    lines := strings.Split(output, "\n")
    // Common patterns:
    // Linux/macOS: rtt min/avg/max/mdev = 0.123/0.456/0.789/0.101 ms
    // Windows: Minimum = 0ms, Maximum = 1ms, Average = 0ms
    for _, line := range lines {
        line = strings.TrimSpace(line)
        if goos == "windows" {
            // Look for "Average = Xms"
            if strings.Contains(line, "Average") && strings.Contains(line, "ms") {
                // Example: "Average = 12ms"
                parts := strings.Split(line, "=")
                if len(parts) >= 2 {
                    valuePart := strings.TrimSpace(parts[len(parts)-1])
                    valuePart = strings.TrimSuffix(valuePart, "ms")
                    valuePart = strings.TrimSpace(valuePart)
                    avg, err := strconv.ParseFloat(valuePart, 64)
                    if err != nil {
                        return 0, fmt.Errorf("invalid average value: %s", valuePart)
                    }
                    return avg, nil
                }
            }
        } else {
            // Linux/macOS pattern: "rtt min/avg/max/mdev = ..."
            if strings.Contains(line, "rtt") && strings.Contains(line, "avg") {
                // Example: "rtt min/avg/max/mdev = 0.123/0.456/0.789/0.101 ms"
                fields := strings.Fields(line)
                for _, field := range fields {
                    if field == "=" {
                        continue
                    }
                    // The field before "ms" is like "0.123/0.456/0.789/0.101"
                    if idx := strings.Index(field, "/"); idx != -1 {
