	var cmd *exec.Cmd

	// Build the ping command according to the operating system.
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		// Linux, macOS, and other Unix-like systems.
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	output := string(out)

	// Parse the output depending on the operating system.
	if runtime.GOOS == "windows" {
		return parseWindowsPing(output)
	}
	return parseUnixPing(output)
}

// parseWindowsPing extracts the average latency from the Windows ping output.
// Expected line: "    Average = 12ms"
func parseWindowsPing(output string) (float64, error) {
	lines := strings.Split(output, "\n")
	for _, line := range lines {
		if strings.Contains(line, "Average") {
			parts := strings.Split(line, "=")
			if len(parts) != 2 {
				continue
			}
			avgStr := strings.TrimSpace(parts[1])
			avgStr = strings.TrimSuffix(avgStr, "ms")
			avgStr = strings.TrimSpace(avgStr)

			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("cannot parse Windows average latency %q: %w", avgStr, err)
			}
			return avg, nil
		}
	}
	return 0, errors.New("average latency not found in Windows ping output")
}

// parseUnixPing extracts the average latency from Unix-like ping output.
// Expected line: "rtt min/avg/max/mdev = 0.123/0.456/0.789/0.111 ms"
// or "round-trip min/avg/max/stddev = ..."
func parseUnixPing(output string) (float64, error) {
	lines := strings.Split(output, "\n")
	for _, line := range lines {
		if strings.Contains(line, "min/avg/max") {
			parts := strings.Split(line, "=")
			if len(parts) != 2 {
				continue
			}
			values := strings.TrimSpace(parts[1])
			// values example: "0.123/0.456/0.789/0.111 ms"
			fields := strings.Split(values, "/")
			if len(fields) < 2 {
				continue
			}
			avgStr := strings.TrimSpace(fields[1])
			// In case "ms" is part of the last field but not here, we strip anyway.
			avgStr = strings.TrimSuffix(avgStr, " ms")
			avgStr = strings.TrimSpace(avgStr)

			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("cannot parse Unix average latency %q: %w", avgStr, err)
			}
			return avg, nil
		}
	}
	return 0, errors.New("average latency not found in Unix ping output")
}

func main() {
	host := "google.com"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency to %s: %v\n", host, err)
		return
	}
	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

