package main

import (
    "fmt"
    "os"
    "os/exec"
    "regexp"
    "runtime"
    "strconv"
)

// MeasureLatency pings the given host a specified number of times and returns
// the average round-trip latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
    if host == "" {
        return 0, fmt.Errorf("host cannot be empty")
    }
    if count <= 0 {
        return 0, fmt.Errorf("count must be positive")
    }

    var cmd *exec.Cmd
    if runtime.GOOS == "windows" {
        cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
    } else {
        cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
    }

    output, err := cmd.Output()
    if err != nil {
        return 0, fmt.Errorf("ping command failed: %w", err)
    }

    outStr := string(output)

    var avg float64
    if runtime.GOOS == "windows" {
        // Windows output example:
        // "    Average = 2ms"
        // "    Average = 1.5ms" (unlikely but possible)
        re := regexp.MustCompile(`Average\s*=\s*(\d+(?:\.\d+)?)`)
        matches := re.FindStringSubmatch(outStr)
        if len(matches) < 2 {
            return 0, fmt.Errorf("failed to parse average latency from ping output")
        }
        avg, err = strconv.ParseFloat(matches[1], 64)
        if err != nil {
            return 0, fmt.Errorf("failed to parse average value: %w", err)
        }
    } else {
        // Unix/Linux output example:
        // "rtt min/avg/max/mdev = 1.234/2.345/3.456/4.567 ms"
        re := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
        matches := re.FindStringSubmatch(outStr)
        if len(matches) < 2 {
            return 0, fmt.Errorf("failed to parse average latency from ping output")
        }
        avg, err = strconv.ParseFloat(matches[1], 64)
        if err != nil {
            return 0, fmt.Errorf("failed to parse average value: %w", err)
        }
    }

    return avg, nil
}

func main() {
    // Default values
    host := "google.com"
    count := 4

    // Override with command-line arguments if provided
    if len(os.Args) >= 2 {
        host = os.Args[1]
    }
    if len(os.Args) >= 3 {
        c, err := strconv.Atoi(os.Args[2])
        if err == nil && c > 0 {
            count = c
        } else {
            fmt.Fprintf(os.Stderr, "Invalid count argument, using default %d\n", count)
        }
    }

    avg, err := MeasureLatency(host, count)
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
        os.Exit(1)
    }
    fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

