package main

import (
    "fmt"
    "os/exec"
    "regexp"
    "runtime"
    "strconv"
)

// MeasureLatency pings the given host a specified number of times and returns
// the average round-trip latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
    if count <= 0 {
        return 0, fmt.Errorf("count must be positive")
    }

    var cmd *exec.Cmd
    if runtime.GOOS == "windows" {
        cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
    } else {
        cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
    }

    out, err := cmd.CombinedOutput()
    if err != nil {
        return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(out))
    }

    // Parse response times from output (supports both "time=12.3 ms" and "time<1 ms" etc.)
    re := regexp.MustCompile(`time[=<]\s*(\d+\.?\d*)\s*ms`)
    matches := re.FindAllStringSubmatch(string(out), -1)

    if len(matches) == 0 {
        return 0, fmt.Errorf("no ping response times found in output")
    }

    var sum float64
    for _, match := range matches {
        t, err := strconv.ParseFloat(match[1], 64)
        if err != nil {
            continue
        }
        sum += t
    }

    if sum == 0 {
        return 0, fmt.Errorf("all response times are zero or unparseable")
    }

    return sum / float64(len(matches)), nil
}

// Example usage
func main() {
    avg, err := MeasureLatency("google.com", 4)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }
    fmt.Printf("Average latency: %.2f ms\n", avg)
}

