package main

import (
    "fmt"
    "os"
    "os/exec"
    "strconv"
    "strings"
)

// MeasureLatency pings a host a specified number of times and returns the
// average round-trip latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
    if count <= 0 {
        return 0, fmt.Errorf("count must be positive")
    }

    cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
    out, err := cmd.Output()
    if err != nil {
        return 0, fmt.Errorf("ping failed: %v", err)
    }

    output := string(out)
    lines := strings.Split(output, "\n")
    for _, line := range lines {
        if !strings.Contains(line, "avg") || !strings.Contains(line, " = ") {
            continue
        }

        parts := strings.Split(line, " = ")
        if len(parts) != 2 {
            continue
        }

        values := strings.Split(parts[1], "/")
        if len(values) < 4 {
            continue
        }

        // The average is the second value (index 1) in the "min/avg/max/mdev" quartet.
        avgStr := values[1]
        avgStr = strings.TrimSpace(avgStr)
        // Remove possible trailing " ms" or "ms".
        avgStr = strings.TrimSuffix(avgStr, " ms")
        avgStr = strings.TrimSuffix(avgStr, "ms")
        avg, err := strconv.ParseFloat(strings.TrimSpace(avgStr), 64)
        if err != nil {
            continue
        }
        return avg, nil
    }

    return 0, fmt.Errorf("could not parse average latency from ping output")
}

func main() {
    if len(os.Args) != 3 {
        fmt.Fprintf(os.Stderr, "Usage: %s <host> <count>\n", os.Args[0])
        os.Exit(1)
    }

    host := os.Args[1]
    count, err := strconv.Atoi(os.Args[2])
    if err != nil || count <= 0 {
        fmt.Fprintf(os.Stderr, "Invalid count: %s\n", os.Args[2])
        os.Exit(1)
    }

    avg, err := MeasureLatency(host, count)
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error: %v\n", err)
        os.Exit(1)
    }

    fmt.Printf("Average latency: %.3f ms\n", avg)
}

