package main

import (
    "flag"
    "fmt"
    "os"
    "os/exec"
    "regexp"
    "runtime"
    "strconv"
)

// MeasureLatency pings the given host count times and returns the average
// round-trip latency in milliseconds. It returns an error if no successful
// replies are received.
func MeasureLatency(host string, count int) (float64, error) {
    if count <= 0 {
        return 0, fmt.Errorf("count must be positive, got %d", count)
    }

    var cmd *exec.Cmd
    switch runtime.GOOS {
    case "windows":
        cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
    default: // linux, darwin, etc.
        cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
    }

    out, err := cmd.Output()
    if err != nil {
        // *exec.ExitError wraps a non-zero exit code, but we still have partial output.
        // We continue parsing whatever was received.
    }

    // Regular expression to capture latency values like "time=12.3 ms" or "time<1ms" or "time=12ms"
    re := regexp.MustCompile(`time[=<](\d+\.?\d*)\s*ms`)
    matches := re.FindAllStringSubmatch(string(out), -1)
    if len(matches) == 0 {
        return 0, fmt.Errorf("no ping replies received from %s", host)
    }

    var total float64
    for _, m := range matches {
        val, err := strconv.ParseFloat(m[1], 64)
        if err != nil {
            return 0, fmt.Errorf("failed to parse latency value %q: %w", m[1], err)
        }
        total += val
    }

    return total / float64(len(matches)), nil
}

func main() {
    host := flag.String("host", "localhost", "target host to ping")
    count := flag.Int("n", 4, "number of ping attempts")
    flag.Parse()

    avg, err := MeasureLatency(*host, *count)
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error: %v\n", err)
        os.Exit(1)
    }
    fmt.Printf("Average latency to %s: %.2f ms\n", *host, avg)
}

